solution:
def sort_colors(colors: list[int]) -> list[int]:
    lo, mid, hi = 0, 0, len(colors) - 1
    while mid <= hi:
        if colors[mid] == 0:
            colors[lo], colors[mid] = colors[mid], colors[lo]
            lo += 1
            mid += 1
        elif colors[mid] == 1:
            mid += 1
        else:
            colors[mid], colors[hi] = colors[hi], colors[mid]
            hi -= 1              # keep mid: the value swapped in is still unchecked
    return colors
